class DatReintegros extends BaseDatReintegros {

    public static function obtenerObjDatRegistroSalarioTiempoServicio($idreintegropersona) {
        return Doctrine::getTable('DatReintegros')->find($idreintegropersona);
    }

    public static function obtenerListadoReintegros($idpersona, $idestructura){
        $sql = Doctrine_Query::create()
               ->from('DatReintegros')
               ->where('idpersona = ? and idestructura = ?', array($idpersona, $idestructura))
               ->fetchArray();
        return $sql;
    }

  public static function existePersonaConNomina($idpersona, $idestructura,$idnomina){
    $sql = Doctrine_Query::create()
      ->from('DatReintegros')
      ->where('idpersona = ? and idestructura = ? and idnomina = ?', array($idpersona,
        $idestructura,$idnomina))
      ->fetchArray();

    return count($sql);
  }

    public static function obtenerDatosPersona($idpersona, $idestructura){
        return Doctrine_Query::create()
            ->select('*')
            ->from('DatReintegros')
            ->where('idpersona = ? and idestructura = ? and operacion = 1', array($idpersona,$idestructura))
            ->orderBy('idelaborarpagos DESC')
            ->fetchArray();
    }

    public static function obtenerAcumulacionTotalPersonaEntidadCUP($idpersona, $idestructura, $moneda){
    return Doctrine_Query::create()
        ->select('sum(importe) as acumuladocup')
        ->from('DatReintegros')
        ->where('idpersona = ? and idestructura = ? and tipomoneda = ? and operacion = 1 ', array($idpersona,$idestructura, $moneda))
        ->fetchOne()
        ->acumuladocup;
}

    public static function obtenerLiquidacionTotalPersonaEntidadCUP($idpersona, $idestructura, $moneda){
        return Doctrine_Query::create()
            ->select('sum(importe) as acumuladocup')
            ->from('DatReintegros')
            ->where('idpersona = ? and idestructura = ? and tipomoneda = ? and operacion = 2', array($idpersona,$idestructura, $moneda))
            ->fetchOne()
            ->acumuladocup;
    }

    public static function obtenerAcumulacionTotalPersonaEntidadCUC($idpersona, $idestructura, $moneda){
        return Doctrine_Query::create()
            ->select('sum(importe) as acumuladocup')
            ->from('DatReintegros')
            ->where('idpersona = ? and idestructura = ? and tipomoneda = ? and operacion = 1 ', array($idpersona,$idestructura, $moneda))
            ->fetchOne()
            ->acumuladocup;
    }

    public static function obtenerLiquidacionTotalPersonaEntidadCUC($idpersona, $idestructura, $moneda){
        return Doctrine_Query::create()
            ->select('sum(importe) as acumuladocup')
            ->from('DatReintegros')
            ->where('idpersona = ? and idestructura = ? and tipomoneda = ? and operacion = 2', array($idpersona,$idestructura, $moneda))
            ->fetchOne()
            ->acumuladocup;
    }

}
